}package com.myjavaworld.jftp.ssl;

import java.security.KeyStore;
import java.security.KeyStoreException;
import java.security.cert.Certificate;
import java.security.cert.X509Certificate;
import java.util.ArrayList;
import java.util.Date;
import java.util.Enumeration;
import java.util.ResourceBundle;

import javax.swing.table.AbstractTableModel;

import com.myjavaworld.util.ResourceLoader;







public class CertificateTableModel extends AbstractTableModel {

	private static ResourceBundle resources = ResourceLoader
			.getBundle("com.myjavaworld.jftp.ssl.CertificateTableModel");
	private static final String[] COLUMN_NAMES = {
			resources.getString("text.subject"),
			resources.getString("text.issuer"),
			resources.getString("text.validFrom"),
			resources.getString("text.validTo") };
	private KeyStore keyStore = null;
	private java.util.List aliases = null;

	public CertificateTableModel(KeyStore keyStore) throws KeyStoreException {
		super();
		setKeyStore(keyStore);
	}

	public void setKeyStore(KeyStore keyStore) throws KeyStoreException {
		this.keyStore = keyStore;
		aliases = new ArrayList();
		Enumeration e = keyStore.aliases();
		while (e.hasMoreElements()) {
			String alias = (String) e.nextElement();
			if (keyStore.isCertificateEntry(alias)) {
				aliases.add(alias);
			}
		}
		fireTableDataChanged();
	}

	public KeyStore getKeyStore() {
		return keyStore;
	}

	public int getColumnCount() {
		return COLUMN_NAMES.length;
	}

	public int getRowCount() {
		return aliases.size();
	}

	@Override
	public String getColumnName(int col) {
		return COLUMN_NAMES[col];
	}

	public Object getValueAt(int row, int col) {
		String alias = (String) aliases.get(row);
		try {
			X509Certificate certificate = (X509Certificate) keyStore
					.getCertificate(alias);
			if (col == 0) {
				String subjectDN = certificate.getSubjectDN().getName();
				String returnValue = DNParser.getParameter(subjectDN, "O");
				return returnValue == null ? "" : returnValue;
			} else if (col == 1) {
				String issuerDN = certificate.getIssuerDN().getName();
				String returnValue = DNParser.getParameter(issuerDN, "O");
				return returnValue == null ? "" : returnValue;
			} else if (col == 2) {
				return certificate.getNotBefore();
			} else if (col == 3) {
				return certificate.getNotAfter();
			}
			return "";
		} catch (KeyStoreException exp) {
			return "Error reading certificate";
		}
	}

	@Override
	public Class getColumnClass(int col) {
		if (col == 2 || col == 3) {
			return Date.class;
		}
		return Object.class;
	}

	public Certificate getCertificateAt(int row) {
		String alias = (String) aliases.get(row);
		try {
			return keyStore.getCertificate(alias);
		} catch (Exception exp) {
			return null;
		}
	}

	public String getAliasAt(int row) {
		return (String) aliases.get(row);
	}
}package com.myjavaworld.jftp.ssl;







public class DNParser {

	private String dn = null;








	public DNParser(String dn) {
		if (dn == null) {
			throw new NullPointerException();
		}
		this.dn = dn;
	}











	public String getParameter(String param) {
		String value = null;
		int startIndex = 0;
		int endIndex = 0;
		param = param + "=";
		String dn = new String(this.dn);

		startIndex = dn.indexOf(param);
		if (startIndex >= 0) {
			dn = dn.substring(startIndex + param.length());
			if (dn.charAt(0) == '\"') {
				endIndex = dn.indexOf('\"', 1);
				if (endIndex < 0) {
					value = dn.substring(1);
				} else {
					value = dn.substring(1, endIndex);
				}
			} else {
				endIndex = dn.indexOf(',');
				if (endIndex < 0) {
					value = dn.substring(0);
				} else {
					value = dn.substring(0, endIndex);
				}
			}
		}
		return value;
	}

	public static String getParameter(String distinguishedName, String param) {
		String value = null;
		int startIndex = 0;
		int endIndex = 0;
		param = param + "=";
		String dn = new String(distinguishedName);

		startIndex = dn.indexOf(param);
		if (startIndex >= 0) {
			dn = dn.substring(startIndex + param.length());
			if (dn.charAt(0) == '\"') {
				endIndex = dn.indexOf('\"', 1);
				if (endIndex < 0) {
					value = dn.substring(1);
				} else {
					value = dn.substring(1, endIndex);
				}
			} else {
				endIndex = dn.indexOf(',');
				if (endIndex < 0) {
					value = dn.substring(0);
				} else {
					value = dn.substring(0, endIndex);
				}
			}
		}
		return value;
	}
