	public SecurityWarningDlg(Frame parent, Certificate[] chain,
			boolean validDate, boolean validHost, boolean trusted) {
		super(parent);
		this.parent = parent;
		this.chain = chain;
		this.validDate = validDate;
		this.validHost = validHost;
		this.trusted = trusted;
		option = NO_OPTION;
