			approved = true;
			okButtonPressed();
			close();
		} else if (evt.getSource().equals(butCancel)) {
			cancelButtonPressed();
			close();
		} else if (evt.getSource().equals(butBrowseLocalDirectory)) {
			browseButtonPressed();
		}
