	private void loadFavorites() {
		java.util.List favorites = new ArrayList();
		try {
			favorites = FavoritesManager.getFavorites();
			model.setFavorites(favorites);
		} catch (Exception exp) {
			GUIUtil.showError(this, exp);
		}
	}

	private void saveFavorites() {
		java.util.List favorites = model.getFavorites();
		try {
			FavoritesManager.saveFavorites(favorites);
		} catch (Exception exp) {
			GUIUtil.showError(this, exp);
		}
	}






	class FavoritesListModel extends AbstractListModel {

		private java.util.List favorites = null;

		public FavoritesListModel() {
			this(new ArrayList());
		}

		public FavoritesListModel(java.util.List favorites) {
			setFavorites(favorites);
		}

		public void setFavorites(java.util.List favorites) {
			if (favorites == null) {
				favorites = new ArrayList();
			}
			this.favorites = favorites;
			Collections.sort(this.favorites);
			fireContentsChanged(this, 0, this.favorites.size());
		}

		public java.util.List getFavorites() {
			return favorites;
		}

		public int getSize() {
			return favorites.size();
		}

		public Object getElementAt(int index) {
			return favorites.get(index);
		}

		public void add(Object obj) {
			favorites.add(obj);
			Collections.sort(favorites);
			fireContentsChanged(this, 0, this.favorites.size());
		}

		public void set(int index, Object obj) {
			favorites.set(index, obj);
			Collections.sort(favorites);
			fireContentsChanged(this, 0, this.favorites.size());
		}

		public Object get(int index) {
			return favorites.get(index);
		}

		public void delete(Collection objects) {
			favorites.removeAll(objects);
			fireContentsChanged(this, 0, this.favorites.size());
		}

		public boolean contains(Object obj) {
			return favorites.contains(obj);
		}
	}
}package com.myjavaworld.jftp;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

import javax.crypto.BadPaddingException;
import javax.crypto.Cipher;
import javax.crypto.IllegalBlockSizeException;
import javax.crypto.NoSuchPaddingException;
import javax.crypto.SealedObject;
import javax.crypto.spec.SecretKeySpec;









public class FavoritesManager {




	private static final File FAV_FILE = new File(JFTP.DATA_HOME,
			"favorites.ser");












	public static List getFavorites() throws IOException,
			ClassNotFoundException, IllegalBlockSizeException,
			BadPaddingException {
		List favorites = new ArrayList();
		FileInputStream fin = null;
		ObjectInputStream in = null;
		try {
			checkFavFile();
			fin = new FileInputStream(FAV_FILE);
			if (fin.available() > 0) {
				in = new ObjectInputStream(fin);
				Object obj = in.readObject();
				if (obj instanceof List) {
					favorites = (List) obj;
					saveFavorites(favorites);
				} else {
					SealedObject so = (SealedObject) obj;
					favorites = (List) so
							.getObject(getCipher(Cipher.DECRYPT_MODE));
				}
			}
			return favorites;
		} finally {
			try {
				if (in != null) {
					in.close();
				}
			} catch (IOException exp) {
			}
			try {
				if (fin != null) {
					fin.close();
				}
			} catch (IOException exp) {
			}
			in = null;
			fin = null;
		}
	}









	public static void saveFavorites(List favorites) throws IOException,
			IllegalBlockSizeException {
		if (favorites == null) {
			favorites = new ArrayList();
		}
		checkDataHome();
		ObjectOutputStream out = null;
		try {
			out = new ObjectOutputStream(new FileOutputStream(FAV_FILE));
			Cipher cipher = getCipher(Cipher.ENCRYPT_MODE);
			if (cipher == null) {


				out.writeObject(favorites);
			} else {
				SealedObject so = new SealedObject((Serializable) favorites,
						cipher);
				out.writeObject(so);
			}
		} finally {
			if (out != null) {
				out.close();
			}
			out = null;
		}
	}











	public static void addFavorite(RemoteHost host) throws IOException,
			ClassNotFoundException, IllegalBlockSizeException,
			BadPaddingException {
		List favorites = getFavorites();
		favorites.add(host);
		saveFavorites(favorites);
	}

	private static void checkDataHome() {
		if (!JFTP.DATA_HOME.exists() || !JFTP.DATA_HOME.isDirectory()) {
			JFTP.DATA_HOME.mkdirs();
		}
	}

	private static void checkFavFile() throws IOException {
		checkDataHome();
		if (!FAV_FILE.exists() || !FAV_FILE.isFile()) {
			FAV_FILE.createNewFile();
		}
	}

	private static Cipher getCipher(int mode) {
		final byte[] encodedKey = { 28, -9, -23, 35, -93, -47, -28, 55, -83,
				-82, 101, -79, 36, 59, 77, -121 };
		Cipher cipher = null;
		try {
			cipher = Cipher.getInstance("AES");
			SecretKeySpec spec = new SecretKeySpec(encodedKey, "AES");
			cipher.init(mode, spec);
			return cipher;
		} catch (InvalidKeyException exp) {
			exp.printStackTrace();
		} catch (NoSuchAlgorithmException exp) {
			exp.printStackTrace();
		} catch (NoSuchPaddingException exp) {
			exp.printStackTrace();
		}
		return null;
	}
