				.getForeground());
		setFont(table.getFont());
		return this;
	}
}package com.myjavaworld.jftp;

import java.util.Comparator;









public class LocalFileComparator implements Comparator {

	public static final int COMPARE_BY_NAME = 1;
	public static final int COMPARE_BY_TYPE = 2;
	public static final int COMPARE_BY_SIZE = 3;
	public static final int COMPARE_BY_DATE = 4;
	public static final int ASC_ORDER = 1;
	public static final int DESC_ORDER = 2;
	private int compareBy = 0;
	private int order = 0;

	public LocalFileComparator() {
		this(COMPARE_BY_NAME, ASC_ORDER);
	}

	public LocalFileComparator(int compareBy) {
		this(compareBy, ASC_ORDER);
	}

	public LocalFileComparator(int compareBy, int order) {
		setCompareBy(compareBy);
		setOrder(order);
	}

	public void setCompareBy(int compareBy) {
		this.compareBy = compareBy;
	}

	public int getCompareBy() {
		return compareBy;
	}

	public void setOrder(int order) {
		this.order = order;
	}

	public int getOrder() {
		return order;
	}

	public int compare(Object o1, Object o2) {
		LocalFile l1 = (LocalFile) o1;
		LocalFile l2 = (LocalFile) o2;
		if (compareBy == COMPARE_BY_NAME) {
			return compareByName(l1, l2);
		} else if (compareBy == COMPARE_BY_SIZE) {
			return compareBySize(l1, l2);
		} else if (compareBy == COMPARE_BY_DATE) {
			return compareByDate(l1, l2);
		} else {
			return compareByType(l1, l2);
		}
	}

	private int compareByName(LocalFile l1, LocalFile l2) {
		int retVal = 0;
		if (l1.isDrive() && !l2.isDrive()) {
			retVal = -1;
		} else if (!l1.isDrive() && l2.isDrive()) {
			retVal = 1;
		} else if (l1.isDirectory() && !l2.isDirectory()) {
			retVal = -1;
		} else if (!l1.isDirectory() && l2.isDirectory()) {
			retVal = 1;
		} else {
			String name1 = l1.isDrive() ? l1.getAbsolutePath() : l1
					.getDisplayName();
			String name2 = l2.isDrive() ? l2.getAbsolutePath() : l2
					.getDisplayName();
			retVal = name1.toUpperCase().compareTo(name2.toUpperCase());
		}
		return order == ASC_ORDER ? retVal : -retVal;
	}

	private int compareBySize(LocalFile l1, LocalFile l2) {
		int retVal = 0;
		if (l1.isDirectory() && !l2.isDirectory()) {
			retVal = -1;
		} else if (!l1.isDirectory() && l2.isDirectory()) {
			retVal = 1;
		} else {
			if (l1.getSize() == l2.getSize()) {
				retVal = 0;
			} else {
				retVal = l1.getSize() < l2.getSize() ? -1 : 1;
			}
			if (retVal == 0) {
				String name1 = l1.isDrive() ? l1.getAbsolutePath() : l1
						.getDisplayName();
				String name2 = l2.isDrive() ? l2.getAbsolutePath() : l2
						.getDisplayName();
				retVal = name1.toUpperCase().compareTo(name2.toUpperCase());
			}
		}
		return order == ASC_ORDER ? retVal : -retVal;
	}

	private int compareByDate(LocalFile l1, LocalFile l2) {
		int retVal = 0;
		if (l1.isDirectory() && !l2.isDirectory()) {
			retVal = -1;
		} else if (!l1.isDirectory() && l2.isDirectory()) {
			retVal = 1;
		} else {
			if (l1.getLastModified() == l2.getLastModified()) {
				retVal = 0;
			} else {
				retVal = l1.getLastModified() < l2.getLastModified() ? -1 : 1;
			}
		}
		return order == ASC_ORDER ? retVal : -retVal;
	}

	private int compareByType(LocalFile l1, LocalFile l2) {
		int retVal = 0;
		if (l1.isDirectory() && !l2.isDirectory()) {
			retVal = -1;
		} else if (!l1.isDirectory() && l2.isDirectory()) {
			retVal = 1;
		} else {
			retVal = l1.getType().compareTo(l2.getType());
			if (retVal == 0) {
				String name1 = l1.isDrive() ? l1.getAbsolutePath() : l1
						.getDisplayName();
				String name2 = l2.isDrive() ? l2.getAbsolutePath() : l2
						.getDisplayName();
				retVal = name1.toUpperCase().compareTo(name2.toUpperCase());
			}
		}
		return order == ASC_ORDER ? retVal : -retVal;
	}
}package com.myjavaworld.jftp;

import com.myjavaworld.util.DateFilter;
import com.myjavaworld.util.Filter;
import com.myjavaworld.util.RegexFilter;





public class LocalFileFilter implements Filter {

	private RegexFilter regexFilter = null;
	private DateFilter dateFilter = null;
	private boolean showHiddenFiles = true;
	private boolean exclusionFilter = false;




	public LocalFileFilter() {
		this(null, null, true, false);
	}







	public LocalFileFilter(RegexFilter regexFilter, DateFilter dateFilter) {
		this(regexFilter, dateFilter, true, false);
	}








	public LocalFileFilter(RegexFilter regexFilter, DateFilter dateFilter,
			boolean showHiddenFiles) {
		this(regexFilter, dateFilter, showHiddenFiles, false);
	}

	public LocalFileFilter(RegexFilter regexFilter, DateFilter dateFilter,
			boolean showHiddenFiles, boolean exclusionFilter) {
		setRegexFilter(regexFilter);
		setDateFilter(dateFilter);
		setShowHiddenFiles(showHiddenFiles);
		setExclusionFilter(exclusionFilter);
	}




	public DateFilter getDateFilter() {
		return dateFilter;
	}





	public void setDateFilter(DateFilter dateFilter) {
		this.dateFilter = dateFilter;
	}




	public RegexFilter getRegexFilter() {
		return regexFilter;
	}





	public void setRegexFilter(RegexFilter regexFilter) {
		this.regexFilter = regexFilter;
	}




	public boolean isShowHiddenFiles() {
		return showHiddenFiles;
	}





	public void setShowHiddenFiles(boolean showHiddenFiles) {
		this.showHiddenFiles = showHiddenFiles;
	}

	public void setExclusionFilter(boolean exclusionFilter) {
		this.exclusionFilter = exclusionFilter;
	}

	public boolean isExclusionFilter() {
		return exclusionFilter;
	}

	public boolean accept(Object value) {
		LocalFile lf = (LocalFile) value;
		if (!showHiddenFiles && lf.isHidden()) {
			return exclusionFilter ? true : false;
		}
		if (lf.isFile()) {
			if (regexFilter != null) {
				if (!regexFilter.accept(lf.getName())) {
					return exclusionFilter ? true : false;
				}
			}
			if (dateFilter != null) {
				if (!dateFilter.accept(new Long(lf.getLastModified()))) {
					return exclusionFilter ? true : false;
				}
			}
			return exclusionFilter ? false : true;
		}
		return true;
	}
