	public void populateScreen() {
		populateScreen(JFTP.prefs);
	}

	public void populateScreen(JFTPPreferences prefs) {
		setProxySettingsEnabled(prefs.isUseProxy());
		cbUseProxy.setSelected(prefs.isUseProxy());
		tfHost.setText(prefs.getProxyHost());
		tfPort.setValue(prefs.getProxyPort());
		tfUser.setText(prefs.getProxyUser());
		tfPassword.setText(new String(prefs.getProxyPassword()));
	}

	public boolean validateFields() {
		String error = null;
		Component errorComponent = null;

		if (cbUseProxy.isSelected()) {
			int port = -1;
			try {
				port = tfPort.getValue();
			} catch (NumberFormatException exp) {
			}
			if (tfHost.getText().trim().length() == 0) {
				error = resources.getString("error.host.required");
				errorComponent = tfHost;
			} else if (port < 0 || port > 0xffff) {
				error = resources.getString("error.port.invalid");
				errorComponent = tfPort;
			}
		}
		if (error == null) {
			return true;
		}
		GUIUtil.showError(this, error);
		errorComponent.requestFocusInWindow();
		return false;
	}

	public void saveChanges() {
		JFTP.prefs.setUseProxy(cbUseProxy.isSelected());
		JFTP.prefs.setProxyHost(tfHost.getText());
		int port = 1080;
		try {
			port = tfPort.getValue();
		} catch (NumberFormatException exp) {
		}
		JFTP.prefs.setProxyPort(port);
		JFTP.prefs.setProxyUser(tfUser.getText());
		JFTP.prefs.setProxyPassword(tfPassword.getPassword());
		JFTPUtil.updateProxySettings();
	}
}package com.myjavaworld.jftp;

import java.awt.Component;

import javax.swing.Icon;
import javax.swing.JTable;

import com.myjavaworld.ftp.RemoteFile;
import com.myjavaworld.gui.MTableCellRenderer;








public class RemoteFileCellRenderer extends MTableCellRenderer {

	private Icon directoryIcon = null;
	private Icon fileIcon = null;

	public RemoteFileCellRenderer() {
		super();
		directoryIcon = JFTPUtil.getIcon("directory16.gif");
		fileIcon = JFTPUtil.getIcon("file16.gif");


	}

	@Override
	public Component getTableCellRendererComponent(JTable table, Object value,
			boolean isSelected, boolean hasFocus, int row, int col) {

		if (value == null) {
			setText("");
			setIcon(null);
		} else {
			RemoteFile file = (RemoteFile) value;
			setText(file.getName());
			setIcon(file.isDirectory() ? directoryIcon : fileIcon);
		}
		setBackground(isSelected ? table.getSelectionBackground() : table
				.getBackground());
		setForeground(isSelected ? table.getSelectionForeground() : table
				.getForeground());
		setFont(table.getFont());
		return this;
	}
}package com.myjavaworld.jftp;

import java.util.Comparator;

import com.myjavaworld.ftp.RemoteFile;










public class RemoteFileComparator implements Comparator {

	public static final int COMPARE_BY_NAME = 1;
	public static final int COMPARE_BY_TYPE = 2;
	public static final int COMPARE_BY_SIZE = 3;
	public static final int COMPARE_BY_DATE = 4;
	public static final int ASC_ORDER = 1;
	public static final int DESC_ORDER = 2;
	private int compareBy = 0;
	private int order = 0;

	public RemoteFileComparator() {
		this(COMPARE_BY_NAME, ASC_ORDER);
	}

	public RemoteFileComparator(int compareBy) {
		this(compareBy, ASC_ORDER);
	}

	public RemoteFileComparator(int compareBy, int order) {
		setCompareBy(compareBy);
		setOrder(order);
	}

	public void setCompareBy(int compareBy) {
		this.compareBy = compareBy;
	}

	public int getCompareBy() {
		return compareBy;
	}

	public void setOrder(int order) {
		this.order = order;
	}

	public int getOrder() {
		return order;
	}

	public int compare(Object o1, Object o2) {
		RemoteFile r1 = (RemoteFile) o1;
		RemoteFile r2 = (RemoteFile) o2;
		if (compareBy == COMPARE_BY_NAME) {
			return compareByName(r1, r2);
		} else if (compareBy == COMPARE_BY_SIZE) {
			return compareBySize(r1, r2);
		} else if (compareBy == COMPARE_BY_DATE) {
			return compareByDate(r1, r2);
		} else {
			return compareByType(r1, r2);
		}
	}

	private int compareByName(RemoteFile r1, RemoteFile r2) {
		int retVal = 0;
		if (r1.isDirectory() && !r2.isDirectory()) {
			retVal = -1;
		} else if (!r1.isDirectory() && r2.isDirectory()) {
			retVal = 1;
		} else {
			retVal = r1.getName().toUpperCase()
					.compareTo(r2.getName().toUpperCase());
		}
		return order == ASC_ORDER ? retVal : -retVal;
	}

	private int compareBySize(RemoteFile r1, RemoteFile r2) {
		int retVal = 0;
		if (r1.isDirectory() && !r2.isDirectory()) {
			retVal = -1;
		} else if (!r1.isDirectory() && r2.isDirectory()) {
			retVal = 1;
		} else {
			if (r1.getSize() == r2.getSize()) {
				retVal = 0;
			} else {
				retVal = r1.getSize() < r2.getSize() ? -1 : 1;
			}
			if (retVal == 0) {
				retVal = r1.getName().toUpperCase()
						.compareTo(r2.getName().toUpperCase());
			}
		}
		return order == ASC_ORDER ? retVal : -retVal;
	}

	private int compareByDate(RemoteFile r1, RemoteFile r2) {
		int retVal = 0;
		if (r1.isDirectory() && !r2.isDirectory()) {
			retVal = -1;
		} else if (!r1.isDirectory() && r2.isDirectory()) {
			retVal = 1;
		} else {
			if (r1.getLastModified() == r2.getLastModified()) {
				retVal = 0;
			} else {
				retVal = r1.getLastModified() < r2.getLastModified() ? -1 : 1;
			}
		}
		return order == ASC_ORDER ? retVal : -retVal;
	}

	private int compareByType(RemoteFile r1, RemoteFile r2) {
		int retVal = 0;
		if (r1.isDirectory() && !r2.isDirectory()) {
			retVal = -1;
		} else if (!r1.isDirectory() && r2.isDirectory()) {
			retVal = 1;
		} else {
			retVal = r1.getType().compareTo(r2.getType());
			if (retVal == 0) {
				retVal = r1.getName().toUpperCase()
						.compareTo(r2.getName().toUpperCase());
			}
		}
		return order == ASC_ORDER ? retVal : -retVal;
	}
